// src/app/(tabs)/profile.tsx
// Real profile: signed-in user, their kids' sizes, size alerts, and order/saved
// counts. Signed-out shows a login prompt. Kids and alerts come from the API.

import { useCallback, useEffect, useState } from 'react';
import { View, Text, Pressable, StyleSheet, ActivityIndicator } from 'react-native';
import { useFocusEffect, useRouter } from 'expo-router';

import { Screen, ScreenBody, TopBar, Monogram, Button } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, text, fonts } from '@/ls/theme';
import {
  children as childrenApi,
  alerts as alertsApi,
  orders as ordersApi,
  favorites as favoritesApi,
  type ApiChild,
  type ApiAlert,
} from '@/ls/api';
import { useSession } from '@/ls/session';

export default function ProfileTab() {
  const router = useRouter();
  const { user, signedIn, signOut } = useSession();

  const [loading, setLoading] = useState(true);
  const [kids, setKids] = useState<ApiChild[]>([]);
  const [activeAlerts, setActiveAlerts] = useState<ApiAlert[]>([]);
  const [orderCount, setOrderCount] = useState(0);
  const [savedCount, setSavedCount] = useState(0);

  const load = useCallback(async () => {
    if (!signedIn) {
      setLoading(false);
      return;
    }
    setLoading(true);
    const [kidsRes, alertsRes, ordersRes, favRes] = await Promise.all([
      childrenApi.list().catch(() => ({ children: [] as ApiChild[] })),
      alertsApi.list().catch(() => ({ alerts: [] as ApiAlert[] })),
      ordersApi.list().catch(() => ({ orders: [] })),
      favoritesApi.list().catch(() => ({ favorites: [] })),
    ]);
    setKids(kidsRes.children);
    setActiveAlerts(alertsRes.alerts.filter((a) => a.active));
    setOrderCount(ordersRes.orders.length);
    setSavedCount(favRes.favorites.length);
    setLoading(false);
  }, [signedIn]);

  useEffect(() => {
    load();
  }, [load]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load]),
  );

  // Is there an active alert for any of this child's sizes?
  const childHasAlert = (c: ApiChild) =>
    activeAlerts.some(
      (a) => c.sizes.includes(a.size) && (a.childId === c.id || a.childId == null),
    );

  if (!signedIn) {
    return (
      <Screen>
        <TopBar title="Profile" />
        <ScreenBody>
          <View style={styles.signedOut}>
            <Monogram size={58} dark />
            <Text style={styles.signedOutTitle}>You’re browsing as a guest</Text>
            <Text style={styles.signedOutBody}>
              Log in to save pairs, set size alerts, and track your orders.
            </Text>
            <View style={styles.signedOutCta}>
              <Button label="Log in" onPress={() => router.push('/login')} />
              <Button variant="outline" label="Create account" onPress={() => router.push('/signup')} />
            </View>
          </View>
        </ScreenBody>
      </Screen>
    );
  }

  return (
    <Screen>
      <TopBar
        title="Profile"
        right={
          <Pressable hitSlop={8} onPress={() => signOut()}>
            <Text style={[styles.link, styles.linkGray]}>Log out</Text>
          </Pressable>
        }
      />

      <ScreenBody>
        {/* identity */}
        <View style={styles.identity}>
          <Monogram size={58} dark />
          <View style={styles.identityMain}>
            <View style={styles.nameLine}>
              <Text style={styles.name}>{user?.name ?? 'Member'}</Text>
            </View>
            <Text style={[text.meta, styles.handle]}>{user?.email}</Text>
          </View>
        </View>

        {/* stats */}
        <View style={styles.statsRow}>
          {[
            ['Kids', String(kids.length)],
            ['Alerts', String(activeAlerts.length)],
            ['Saved', String(savedCount)],
          ].map(([label, val], i) => (
            <View key={label} style={[styles.stat, i < 2 && styles.statBorder]}>
              <Text style={styles.statVal}>{val}</Text>
              <Text style={[text.cardFrom, styles.statLabel]}>{label}</Text>
            </View>
          ))}
        </View>

        {loading ? (
          <View style={styles.loadingWrap}>
            <ActivityIndicator color={colors.black} />
          </View>
        ) : (
          <>
            {/* YOUR KIDS' SIZES — repeat-buyer hook */}
            <View style={styles.sec}>
              <View style={styles.secHead}>
                <Text style={text.eyebrow}>Your kids’ sizes</Text>
                <Pressable hitSlop={8} onPress={() => router.push('/add-size')}>
                  <Text style={[styles.link, styles.linkGray]}>Add</Text>
                </Pressable>
              </View>
              <View style={styles.kidsList}>
                {kids.map((k) => (
                  <View key={k.id} style={styles.kidCard}>
                    <View style={styles.kidAvatar}>
                      <Text style={styles.kidAvatarText}>{k.name[0]?.toUpperCase()}</Text>
                    </View>
                    <View style={styles.kidMain}>
                      <Text style={styles.kidName}>{k.name}</Text>
                      <Text style={[text.meta, styles.kidSize]}>
                        {k.sizes.length > 1 ? 'Sizes ' : 'Size '}
                        {k.sizes.join(', ')}
                      </Text>
                    </View>
                    {childHasAlert(k) ? (
                      <View style={styles.alertsOn}>
                        <Icon.bell w={13} h={13} strokeWidth={2} />
                        <Text style={styles.alertsOnText}>Alerts on</Text>
                      </View>
                    ) : null}
                  </View>
                ))}
                <Pressable style={styles.addKid} onPress={() => router.push('/add-size')}>
                  <Icon.plus w={16} h={16} strokeWidth={2.2} stroke={colors.gray} />
                  <Text style={styles.addKidText}>Add a child</Text>
                </Pressable>
              </View>
            </View>

            {/* quick links */}
            <View style={styles.quickLinks}>
              <Pressable style={[styles.qlRow, styles.qlRowFirst]} onPress={() => router.push('/(tabs)/activity')}>
                <Icon.heart w={19} h={19} strokeWidth={1.9} />
                <Text style={styles.qlTitle}>Watchlist</Text>
                <Text style={text.meta}>{savedCount} saved</Text>
                <Icon.chevR w={15} h={15} strokeWidth={2.2} stroke={colors.gray} />
              </Pressable>
              <Pressable style={[styles.qlRow, styles.qlRowLast]} onPress={() => router.push('/(tabs)/activity')}>
                <Icon.box w={19} h={19} strokeWidth={1.9} />
                <Text style={styles.qlTitle}>Orders</Text>
                <Text style={text.meta}>{orderCount} total</Text>
                <Icon.chevR w={15} h={15} strokeWidth={2.2} stroke={colors.gray} />
              </Pressable>
            </View>

            {/* seller CTA */}
            <View style={styles.ctaWrap}>
              <Button
                small
                label="List an item"
                onPress={() => router.push('/(tabs)/sell')}
                left={<Icon.plus w={18} h={18} strokeWidth={2.2} stroke={colors.white} />}
              />
            </View>
          </>
        )}
        <View style={styles.bottomSpacer} />
      </ScreenBody>
    </Screen>
  );
}

const styles = StyleSheet.create({
  link: { fontFamily: fonts.semibold, fontWeight: '600', fontSize: 12, letterSpacing: 0.02 * 12, color: colors.black },
  linkGray: { color: colors.gray },

  // signed out
  signedOut: { alignItems: 'center', paddingHorizontal: 28, paddingVertical: 48, gap: 10 },
  signedOutTitle: { fontFamily: fonts.bold, fontWeight: '700', fontSize: 17, color: colors.black, marginTop: 8, textAlign: 'center' },
  signedOutBody: { fontFamily: fonts.regular, fontWeight: '400', fontSize: 13.5, lineHeight: 13.5 * 1.5, color: colors.gray, textAlign: 'center', maxWidth: 280 },
  signedOutCta: { marginTop: 18, alignSelf: 'stretch', gap: 10 },

  loadingWrap: { paddingVertical: 40, alignItems: 'center' },

  // identity
  identity: { flexDirection: 'row', alignItems: 'center', gap: 14, paddingHorizontal: 16, paddingTop: 8, paddingBottom: 18 },
  identityMain: { flex: 1 },
  nameLine: { flexDirection: 'row', alignItems: 'center', gap: 7 },
  name: { fontFamily: fonts.extrabold, fontWeight: '800', fontSize: 19, color: colors.black },
  handle: { marginTop: 2 },

  // stats
  statsRow: { flexDirection: 'row', borderTopWidth: 1, borderBottomWidth: 1, borderColor: colors.line },
  stat: { flex: 1, alignItems: 'center', paddingVertical: 16 },
  statBorder: { borderRightWidth: 1, borderRightColor: colors.line },
  statVal: { fontFamily: fonts.extrabold, fontWeight: '800', fontSize: 20, color: colors.black },
  statLabel: { fontSize: 10, marginTop: 2 },

  // section
  sec: { paddingHorizontal: 16, paddingTop: 18, paddingBottom: 8 },
  secHead: { flexDirection: 'row', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: 12 },

  // kids
  kidsList: { flexDirection: 'column', gap: 10 },
  kidCard: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
    borderWidth: 1,
    borderColor: colors.line,
    borderRadius: 12,
    paddingVertical: 12,
    paddingHorizontal: 14,
  },
  kidAvatar: {
    width: 38,
    height: 38,
    borderRadius: 999,
    backgroundColor: colors.lightGray,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  kidAvatarText: { fontFamily: fonts.extrabold, fontWeight: '800', fontSize: 13, color: colors.black },
  kidMain: { flex: 1 },
  kidName: { fontFamily: fonts.bold, fontWeight: '700', fontSize: 14, color: colors.black },
  kidSize: { marginTop: 1 },
  alertsOn: { flexDirection: 'row', alignItems: 'center', gap: 6 },
  alertsOnText: {
    fontFamily: fonts.bold,
    fontWeight: '700',
    fontSize: 10.5,
    letterSpacing: 0.06 * 10.5,
    textTransform: 'uppercase',
    color: colors.black,
  },
  addKid: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 7,
    borderWidth: 1.5,
    borderStyle: 'dashed',
    borderColor: colors.gray2,
    borderRadius: 12,
    paddingVertical: 12,
    paddingHorizontal: 14,
  },
  addKidText: { fontFamily: fonts.bold, fontWeight: '700', fontSize: 13, color: colors.gray },

  // quick links
  quickLinks: { paddingHorizontal: 16, paddingBottom: 4, paddingTop: 8 },
  qlRow: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 14, borderTopWidth: 1, borderTopColor: colors.line },
  qlRowFirst: {},
  qlRowLast: { borderBottomWidth: 1, borderBottomColor: colors.line },
  qlTitle: { flex: 1, fontFamily: fonts.bold, fontWeight: '700', fontSize: 14, color: colors.black },

  // cta
  ctaWrap: { padding: 16 },

  bottomSpacer: { height: 12 },
});
