// src/ls/motion.tsx
// Shared motion primitives. Reanimated-only so everything stays Expo-Go-safe
// and cheap on web. Curves are ease-out, 150-350ms, subtle. Premium = restraint.

import React from 'react';
import { Pressable, PressableProps, StyleProp, ViewStyle } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withSpring,
  Easing,
} from 'react-native-reanimated';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

// House easing — a soft ease-out used across entrances and feedback.
export const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

// Stagger step for cascading lists/shelves (ms between siblings).
export const STAGGER_MS = 45;

// Spring config for "pop" moments (favorite heart). Snappy but not bouncy.
export const POP_SPRING = { damping: 12, stiffness: 320, mass: 0.6 } as const;

export type PressableScaleProps = PressableProps & {
  /** Scale at full press. Default 0.97 (subtle). */
  pressScale?: number;
  /** Opacity at full press. Default 0.92. */
  pressOpacity?: number;
  style?: StyleProp<ViewStyle>;
  children?: React.ReactNode;
};

/**
 * Drop-in Pressable with a buttery scale-down + opacity dip on press.
 * Uses reanimated shared values (UI thread) so it never drops a frame.
 */
export function PressableScale({
  pressScale = 0.97,
  pressOpacity = 0.92,
  style,
  children,
  onPressIn,
  onPressOut,
  ...rest
}: PressableScaleProps) {
  const active = useSharedValue(0);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [
      {
        scale: withTiming(1 - active.value * (1 - pressScale), {
          duration: 140,
          easing: EASE_OUT,
        }),
      },
    ],
    opacity: withTiming(1 - active.value * (1 - pressOpacity), {
      duration: 140,
      easing: EASE_OUT,
    }),
  }));

  return (
    <AnimatedPressable
      {...rest}
      style={[style, animatedStyle]}
      onPressIn={(e) => {
        active.value = 1;
        onPressIn?.(e);
      }}
      onPressOut={(e) => {
        active.value = 0;
        onPressOut?.(e);
      }}
    >
      {children}
    </AnimatedPressable>
  );
}

export { Animated, useSharedValue, useAnimatedStyle, withTiming, withSpring };
