import { useEffect, useState } from 'react';
import { View, Text, StyleSheet, ActivityIndicator } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import Animated, {
  FadeInDown,
  useSharedValue,
  useAnimatedStyle,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import { Screen, ScreenBody, PH, Button, FadeImage, dualCTA } from '@/ls/ui';
import { POP_SPRING } from '@/ls/motion';
import { notifySuccess } from '@/ls/haptics';
import { Icon } from '@/ls/icons';
import { colors, text } from '@/ls/theme';
import { mockImage } from '@/ls/data';
import { orders, type ApiOrder } from '@/ls/api';

const STEPS = ['Ordered', 'Packed', 'Shipped', 'Delivered'];
const STEP_INDEX: Record<string, number> = {
  pending: 0,
  paid: 0,
  shipped: 2,
  delivered: 3,
  cancelled: 0,
};

export default function ConfirmationScreen() {
  const router = useRouter();
  const { orderId } = useLocalSearchParams<{ orderId?: string }>();

  const [order, setOrder] = useState<ApiOrder | null>(null);
  const [loading, setLoading] = useState(true);

  // Success moment: the check circle springs up from nothing with a soft ring
  // pulse behind it, fired once on mount alongside a success haptic.
  const checkScale = useSharedValue(0);
  const ringScale = useSharedValue(0);
  const ringOpacity = useSharedValue(0);

  useEffect(() => {
    checkScale.value = withSequence(
      withTiming(1.15, { duration: 280 }),
      withSpring(1, POP_SPRING),
    );
    ringOpacity.value = withSequence(
      withTiming(0.18, { duration: 220 }),
      withTiming(0, { duration: 520 }),
    );
    ringScale.value = withTiming(2.1, { duration: 740 });
    notifySuccess();
  }, [checkScale, ringScale, ringOpacity]);

  const checkStyle = useAnimatedStyle(() => ({ transform: [{ scale: checkScale.value }] }));
  const ringStyle = useAnimatedStyle(() => ({
    opacity: ringOpacity.value,
    transform: [{ scale: ringScale.value }],
  }));

  useEffect(() => {
    let alive = true;
    if (!orderId) {
      setLoading(false);
      return;
    }
    orders
      .get(String(orderId))
      .then((res) => {
        if (alive) setOrder(res.order);
      })
      .catch(() => {
        // Order placed but fetch failed — still show the success screen.
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [orderId]);

  const activeStep = order ? STEP_INDEX[order.status] ?? 0 : 0;
  const listing = order?.listing;
  const photo = listing?.imageUrl ? { uri: listing.imageUrl } : listing ? mockImage(listing.sku) : null;
  const orderNo = order ? `LS-${order.id.slice(-6).toUpperCase()}` : '...';

  return (
    <Screen>
      <ScreenBody contentContainerStyle={styles.bodyContent}>
        <View style={styles.center}>
          <View style={styles.checkWrap}>
            <Animated.View style={[styles.ring, ringStyle]} />
            <Animated.View style={[styles.checkCircle, checkStyle]}>
              <Icon.check w={36} h={36} strokeWidth={2.6} stroke={colors.white} />
            </Animated.View>
          </View>
          <Animated.Text entering={FadeInDown.duration(420).delay(180)} style={[text.hLg, styles.heading]}>
            Order{'\n'}Confirmed
          </Animated.Text>
          <Animated.Text entering={FadeInDown.duration(420).delay(280)} style={[text.body, styles.reassure]}>
            Packed by the seller and on its way. Covered by LS Protect, so you’re refunded or credited if it’s not as described.
          </Animated.Text>

          {/* order card */}
          <Animated.View entering={FadeInDown.duration(420).delay(380)} style={styles.card}>
            {loading ? (
              <View style={styles.cardLoading}>
                <ActivityIndicator color={colors.black} />
              </View>
            ) : (
              <>
                <View style={styles.row}>
                  <View style={styles.rowThumb}>
                    {photo ? <FadeImage source={photo} resizeMode="contain" style={styles.thumbImg} /> : <PH label="" />}
                  </View>
                  <View style={styles.rowMain}>
                    <Text style={styles.rowTitle}>
                      {listing ? `${listing.brand}, ${listing.name}` : 'Your order'}
                    </Text>
                    <Text style={text.meta}>
                      {listing?.size ? `Size ${listing.size} · ` : ''}Order #{orderNo}
                    </Text>
                  </View>
                </View>

                {/* progress */}
                <View style={styles.progress}>
                  <View style={styles.track}>
                    {STEPS.map((s, i) => [
                      <View key={`${s}-n`} style={[styles.node, i <= activeStep ? styles.nodeActive : styles.nodeIdle]} />,
                      i < 3 ? <View key={`${s}-l`} style={styles.line} /> : null,
                    ])}
                  </View>
                  <View style={styles.labels}>
                    {STEPS.map((s, i) => (
                      <Text key={s} style={[styles.stepLabel, i <= activeStep ? styles.stepActive : styles.stepIdle]}>
                        {s}
                      </Text>
                    ))}
                  </View>
                </View>
              </>
            )}
          </Animated.View>
        </View>

        <Animated.View entering={FadeInDown.duration(420).delay(460)} style={styles.estWrap}>
          <Text style={styles.est}>Est. delivery in 5 to 7 days</Text>
        </Animated.View>
      </ScreenBody>

      <View style={dualCTA}>
        <Button
          variant="outline"
          label="Track order"
          style={styles.cta}
          onPress={() => router.replace('/(tabs)/activity')}
        />
        <Button
          label="Keep shopping"
          style={styles.cta}
          onPress={() => router.replace('/(tabs)')}
        />
      </View>
    </Screen>
  );
}

