// src/ls/icons.tsx
// Little Soles icon set — ported from from_design/ls-shared.jsx to react-native-svg.
// RN has no `currentColor`; pass `stroke`/`fill` props. Default stroke = black.

import React from 'react';
import { Svg, Path, Circle, Rect, G } from 'react-native-svg';

export type IconProps = {
  /** Convenience: sets both width and height. */
  size?: number;
  /** Width override (falls back to size, then 22). */
  w?: number;
  /** Height override (falls back to size, then 22). */
  h?: number;
  stroke?: string;
  fill?: string;
  /** strokeWidth. Mirrors the `s` prop from the design source. */
  strokeWidth?: number;
};

type BaseProps = IconProps & {
  vb?: string;
  children: React.ReactNode;
};

// Shared SVG wrapper. Defaults match the design's <I> component.
const Base = ({
  size,
  w,
  h,
  vb = '0 0 24 24',
  children,
}: BaseProps) => {
  const width = w ?? size ?? 22;
  const height = h ?? size ?? 22;
  return (
    <Svg width={width} height={height} viewBox={vb}>
      {children}
    </Svg>
  );
};

// Default stroke/strokeWidth/fill per the design (<I s=1.8 stroke=currentColor fill=none>).
const defaults = (p: IconProps) => ({
  stroke: p.stroke ?? '#000',
  strokeWidth: p.strokeWidth ?? 1.8,
  fill: p.fill ?? 'none',
  strokeLinecap: 'round' as const,
  strokeLinejoin: 'round' as const,
});

