import { useRouter } from 'expo-router';
import Animated, { FadeIn, FadeInDown } from 'react-native-reanimated';

import { Screen, ScreenBody, TopBar, Brand, ProductCard, Divider, Skeleton } from '@/ls/ui';
import { PressableScale } from '@/ls/motion';
import { Icon } from '@/ls/icons';
import { colors, radii, text, fonts } from '@/ls/theme';
import { getCatalog, mockImage } from '@/ls/data';
import { useSession } from '@/ls/session';
import type { DisplayListing } from '@/ls/api';

// A horizontal shelf of listings. Shows a small skeleton row while loading and
// a quiet empty note if the shelf has nothing (e.g. API returned fewer pairs).
function Shelf({
  items,
  loading,
  onPress,
  contentStyle,
}: {
  items: DisplayListing[];
  loading: boolean;
  onPress: (l: DisplayListing) => void;
  contentStyle?: any;
}) {
  if (loading) {
    return (
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={[styles.hscroll, contentStyle]}>
        {[0, 1, 2].map((i) => (
          <Skeleton key={i} style={[styles.hcard, styles.skel]} />
        ))}
      </ScrollView>
    );
  }
  if (!items.length) {
    return (
      <View style={styles.shelfEmpty}>
        <Text style={styles.shelfEmptyText}>Nothing here yet. Check back soon.</Text>
      </View>
    );
  }
  return (
    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={[styles.hscroll, contentStyle]}>
      {items.map((l, i) => (
        <Animated.View
          key={`${l.id}-${i}`}
          entering={FadeInDown.duration(320).delay(Math.min(i, 6) * 45)}
          style={styles.hcard}
        >
          <ProductCard
            brand={l.brand}
            name={l.name}
            price={l.price}
            cond={l.cond}
            image={l.imageUrl ? { uri: l.imageUrl } : mockImage(l.sku)}
            onPress={() => onPress(l)}
          />
        </Animated.View>
      ))}
    </ScrollView>
  );
}

// Section head with title, sub, and a "View all" link.
function ShelfHead({
  title,
  sub,
  onViewAll,
}: {
  title: string;
  sub?: string;
  onViewAll: () => void;
}) {
  return (
    <View style={styles.secHead}>
      <View style={styles.secHeadText}>
        <Text style={[text.hMd, styles.shelfTitle]}>{title}</Text>
        {sub ? <Text style={[text.meta, styles.shelfSub]}>{sub}</Text> : null}
      </View>
      <Pressable onPress={onViewAll} hitSlop={8}>
        <Text style={styles.link}>View all</Text>
      </Pressable>
    </View>
  );
}

type SizeChip = { key: string; label: string; name: string; size: string };

// Fallback chips for signed-out / no-kids — generic, not a fake "Mia".
const FALLBACK_CHIPS: SizeChip[] = [
  { key: 'sz-10c', label: '10C', name: '', size: '10C' },
  { key: 'sz-13c', label: '13C', name: '', size: '13C' },
];

export default function HomeTab() {
  const router = useRouter();
  const { signedIn } = useSession();

  const [sizeChips, setSizeChips] = useState<SizeChip[]>(FALLBACK_CHIPS);
  const [activeChild, setActiveChild] = useState<string>(FALLBACK_CHIPS[0].key);

  const [items, setItems] = useState<DisplayListing[]>([]);
  const [loading, setLoading] = useState(true);

  // Pull real children when signed in so the "Shop ___'s size" rail reflects the
  // family. Signed out (or no kids), keep the generic size fallback above.
  useEffect(() => {
    if (!signedIn) {
      setSizeChips(FALLBACK_CHIPS);
      setActiveChild(FALLBACK_CHIPS[0].key);
      return;
    }
    let alive = true;
    import('@/ls/api').then(({ children }) => {
      children
        .list()
        .then(({ children: kids }) => {
          if (!alive || !kids?.length) return;
          // A kid can carry multiple sizes; render one chip per (kid, size) so
          // each size stays a single, shoppable filter.
          const chips: SizeChip[] = kids.flatMap((k) =>
            (k.sizes ?? []).map((size) => ({
              key: `${k.id}:${size}`,
              label: `${k.name} · ${size}`,
              name: k.name,
              size,
            })),
          );
          if (!chips.length) return;
          setSizeChips(chips);
          setActiveChild(chips[0].key);
        })
        .catch(() => {
          /* keep fallback on any error */
        });
    });
    return () => {
      alive = false;
    };
  }, [signedIn]);

  const active = sizeChips.find((c) => c.key === activeChild) ?? sizeChips[0];
  const sizeHeading = active?.name ? `Shop ${active.name}'s size` : 'Shop by size';
  const alertSize = active?.size ?? '10C';

  // Load the catalog once. getCatalog() falls back to the mock list on any API
  // error, so browse never hard-fails even on a Render cold start miss.
  useEffect(() => {
    let alive = true;
    getCatalog({ sort: 'newest' })
      .then((rows) => {
        if (alive) setItems(rows);
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, []);

  const openListing = (l: DisplayListing) => router.push(`/product/${l.id}`);

  // Curated shelves are slices of the single feed (keeps the design's rhythm
  // without 4 separate round trips). Cheapest-first for "Under Retail".
  const justDropped = items;
  const underRetail = [...items].sort((a, b) => a.price - b.price);
  const selects = items;
  const mySizeShelf = items.slice(0, 6);

  return (
    <Screen>
      {/* Top bar: brand + search/person icons */}
      <TopBar
        left={<Brand size={18} />}
        right={
          <View style={styles.topActions}>
            <PressableScale
              style={styles.iconBtn}
              pressScale={0.88}
              onPress={() => router.push('/(tabs)/search')}
              hitSlop={6}
            >
              <Icon.search w={22} h={22} strokeWidth={1.9} />
            </PressableScale>
            <PressableScale
              style={styles.iconBtn}
              pressScale={0.88}
              onPress={() => router.push('/(tabs)/profile')}
              hitSlop={6}
            >
              <Icon.person w={22} h={22} strokeWidth={1.9} />
            </PressableScale>
          </View>
        }
      />

      {/* Trust strip — loud, thin */}
      <View style={styles.trustStrip}>
        {['Curated', 'Protected', 'No seller fees'].map((t, i, a) => (
          <React.Fragment key={t}>
            <View style={styles.trustItem}>
              <Icon.check w={11} h={11} strokeWidth={3} />
              <Text style={styles.trustText}>{t}</Text>
            </View>
            {i < a.length - 1 ? <Text style={styles.trustDot}>·</Text> : null}
          </React.Fragment>
        ))}
      </View>

      <ScreenBody>
        {/* Hero banner */}
        <Animated.View entering={FadeInDown.duration(360)} style={styles.heroWrap}>
          <View style={styles.hero}>
            <Image
              source={require('../../../assets/shoes/j4.jpg')}
              resizeMode="contain"
              style={styles.heroImg}
            />
            <View style={styles.heroCopy}>
              <Text style={styles.heroEyebrow}>LITTLE SOLES SELECTS</Text>
              <Text style={[text.hLg, styles.heroTitle]}>Premium{'\n'}Jordans</Text>
              <Text style={styles.heroSub}>Protected pairs from $52</Text>
            </View>
          </View>
        </Animated.View>

        {/* Shop by size */}
        <View style={styles.sizeSection}>
          <View style={styles.sizeHead}>
            <Text style={[text.hMd, styles.shelfTitle, styles.sizeHeadTitle]}>
              {sizeHeading}
            </Text>
            <Pressable onPress={() => router.push('/(tabs)/profile')} hitSlop={8}>
              <Text style={[styles.link, styles.linkGray]}>Manage sizes</Text>
            </Pressable>
          </View>

          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.chipRow}
          >
            {sizeChips.map((c) => {
              const on = activeChild === c.key;
              return (
                <PressableScale
                  key={c.key}
                  onPress={() => setActiveChild(c.key)}
                  pressScale={0.95}
                  style={[styles.fchip, on && styles.fchipActive]}
                >
                  <Text style={[styles.fchipText, on && styles.fchipTextActive]}>
                    {c.label}
                  </Text>
                </PressableScale>
              );
            })}
            <PressableScale
              style={styles.fchip}
              pressScale={0.95}
              onPress={() => router.push('/(tabs)/profile')}
            >
              <Icon.plus w={14} h={14} strokeWidth={2.2} />
              <Text style={styles.fchipText}>Add child</Text>
            </PressableScale>
          </ScrollView>

          <View style={styles.alertNote}>
            <Icon.bell w={17} h={17} strokeWidth={1.9} />
            <Text style={styles.alertText}>
              Alerts on for {alertSize}, we&rsquo;ll ping you when new pairs drop.
            </Text>
          </View>

          <Shelf items={mySizeShelf} loading={loading} onPress={openListing} />
        </View>

        <Divider style={styles.divider} />

        {/* Under Retail */}
        <ShelfHead
          title="Under Retail"
          sub="Premium pairs, less than store price"
          onViewAll={() => router.push('/(tabs)/search')}
        />
        <Shelf items={underRetail} loading={loading} onPress={openListing} contentStyle={styles.shelfBottom} />

        {/* Just Dropped */}
        <ShelfHead
          title="Just Dropped"
          sub="Fresh pairs this week"
          onViewAll={() => router.push('/(tabs)/search')}
        />
        <Shelf items={justDropped} loading={loading} onPress={openListing} contentStyle={styles.shelfBottom} />

        {/* Little Soles Selects */}
        <ShelfHead
          title="Little Soles Selects"
          sub="Hand-picked by our team"
          onViewAll={() => router.push('/(tabs)/search')}
        />
        <Shelf items={selects} loading={loading} onPress={openListing} />

        <View style={styles.footSpace} />
      </ScreenBody>
    </Screen>
  );
}

