// src/ls/api.ts
// Typed client for the Little Soles backend (ls-api). PURELY ADDITIVE.
// Nothing imports this yet except src/ls/data.ts; screens stay on the mock
// until a later phase wires them in. Shapes mirror ls-api/README.md.

import { API_BASE_URL } from './config';
import { getToken, setToken, clearToken } from './storage';
import type { CatalogItem, ConditionKey } from './catalog';

// ─────────────────────────────────────────────────────────────
// Errors
// ─────────────────────────────────────────────────────────────

/** Thrown on any non-2xx response. `status` is the HTTP code. */
export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
  }
}

// ─────────────────────────────────────────────────────────────
// Wire types — match ls-api responses (money is integer cents; list/detail
// also include a derived `price` in dollars).
// ─────────────────────────────────────────────────────────────

export type ApiCondition = 'cert' | 'nib' | 'nnb' | 'worn' | 'play';
export type ApiListingStatus = 'active' | 'pending' | 'sold';
export type ApiOfferStatus = 'pending' | 'accepted' | 'declined' | 'expired';
export type ApiOrderStatus =
  | 'pending'
  | 'paid'
  | 'shipped'
  | 'delivered'
  | 'cancelled';

export interface ApiUser {
  id: string;
  email: string;
  name: string;
}

export interface ApiListing {
  id: string;
  sku: string;
  brand: string;
  name: string;
  colorway: string;
  size: string;
  priceCents: number;
  /** Derived dollars, included by list/detail endpoints. */
  price: number;
  condition: ApiCondition;
  status: ApiListingStatus;
  imageUrl: string | null;
  createdAt: string;
}

/** Detail endpoint enriches the listing with seller + offer context. */
export interface ApiListingDetail extends ApiListing {
  seller?: { id: string; name: string } | null;
  recentOffers?: ApiOffer[];
  lowestPendingOfferCents?: number | null;
}

export interface Favorite {
  id: string;
  createdAt: string;
  listing: ApiListing;
}

export interface ApiChild {
  id: string;
  name: string;
  /** A kid carries 1 to 4 sizes (different brands/types, plus growth room). */
  sizes: string[];
}

export interface ApiAlert {
  id: string;
  size: string;
  brand: string | null;
  childId: string | null;
  active: boolean;
  /** Live count of matching active listings, returned by GET /alerts. */
  matchCount?: number;
  createdAt?: string;
}

export interface ApiOffer {
  id: string;
  listingId: string;
  amountCents: number;
  status: ApiOfferStatus;
  createdAt: string;
  listing?: ApiListing;
}

export interface ApiOrder {
  id: string;
  listingId: string;
  paymentIntentId: string;
  amountCents: number;
  status: ApiOrderStatus;
  shippingAddress: ShippingAddress | string;
  createdAt: string;
  listing?: ApiListing;
}

export interface ShippingAddress {
  name: string;
  line1: string;
  line2?: string;
  city: string;
  state: string;
  postalCode: string;
  country: string;
}

export interface AuthResponse {
  token: string;
  user: ApiUser;
}

export interface PaymentIntentResponse {
  clientSecret: string;
  paymentIntentId: string;
  /** Listing price alone, before the LS Protect fee. */
  itemCents?: number;
  /** Buyer-side LS Protect fee (7% + 70¢), computed by the server. */
  feeCents?: number;
  amountCents: number;
  simulated: boolean;
}

// ─────────────────────────────────────────────────────────────
// Core request helper
// ─────────────────────────────────────────────────────────────

type Method = 'GET' | 'POST' | 'PATCH' | 'DELETE';

interface RequestOptions {
  method?: Method;
  body?: unknown;
  /** When true, attaches `Authorization: Bearer <stored token>`. */
  auth?: boolean;
  /** Per-request timeout in ms. Defaults to REQUEST_TIMEOUT_MS. */
  timeoutMs?: number;
}

/**
 * Render's free tier cold-starts up to ~50s after idle. We allow 60s so the
 * very first call after a sleep still resolves instead of aborting; every warm
 * call returns in well under a second, so this ceiling only bites on cold boot.
 */
export const REQUEST_TIMEOUT_MS = 90_000;

/**
 * Fire-and-forget wake-up call for Render's free tier. Called once at app
 * launch so the backend is already warm (or warming) by the time the user
 * reaches login. Errors are swallowed — this is purely opportunistic.
 */
export function warmUp(): void {
  fetch(API_BASE_URL + '/api/health').catch(() => {});
}

export async function request<T>(
  path: string,
  { method = 'GET', body, auth = false, timeoutMs = REQUEST_TIMEOUT_MS }: RequestOptions = {},
): Promise<T> {
  const headers: Record<string, string> = { Accept: 'application/json' };

  if (body !== undefined) headers['Content-Type'] = 'application/json';

  if (auth) {
    const token = await getToken();
    if (token) headers['Authorization'] = `Bearer ${token}`;
  }

  // Abort on timeout so a cold/unreachable backend surfaces a clean error
  // instead of hanging the UI forever.
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  let res: Response;
  try {
    res = await fetch(API_BASE_URL + path, {
      method,
      headers,
      body: body !== undefined ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
  } catch (err) {
    clearTimeout(timer);
    if (err instanceof Error && err.name === 'AbortError') {
      throw new ApiError(0, 'The server took too long to respond. Please try again.');
    }
    throw new ApiError(0, 'Cannot reach Little Soles right now. Check your connection and try again.');
  }
  clearTimeout(timer);

  // 204 No Content (DELETE) — nothing to parse.
  if (res.status === 204) return undefined as T;

  const raw = await res.text();
  let parsed: any = null;
  if (raw) {
    try {
      parsed = JSON.parse(raw);
    } catch {
      parsed = raw;
    }
  }

  if (!res.ok) {
    const message =
      (parsed && (parsed.error || parsed.message)) ||
      (typeof parsed === 'string' && parsed) ||
      `Request failed with status ${res.status}`;
    throw new ApiError(res.status, String(message));
  }

  return parsed as T;
}

// ─────────────────────────────────────────────────────────────
// Query string helper
// ─────────────────────────────────────────────────────────────

function qs(params: Record<string, unknown>): string {
  const parts: string[] = [];
  for (const [k, v] of Object.entries(params)) {
    if (v === undefined || v === null || v === '') continue;
    parts.push(`${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`);
  }
  return parts.length ? `?${parts.join('&')}` : '';
}

// ─────────────────────────────────────────────────────────────
// Auth
// ─────────────────────────────────────────────────────────────

export const auth = {
  async signup(input: { email: string; password: string; name: string }): Promise<AuthResponse> {
    const res = await request<AuthResponse>('/api/auth/signup', { method: 'POST', body: input });
    await setToken(res.token);
    return res;
  },
  async login(input: { email: string; password: string }): Promise<AuthResponse> {
    const res = await request<AuthResponse>('/api/auth/login', { method: 'POST', body: input });
    await setToken(res.token);
    return res;
  },
  /**
   * Social sign-in. The client completes the Apple/Google flow, then hands the
   * provider's signed id token here; the server verifies it and find-or-creates
   * the user. Same { token, user } contract as login/signup.
   */
  async oauth(input: {
    provider: 'apple' | 'google';
    idToken: string;
    name?: string;
  }): Promise<AuthResponse> {
    const res = await request<AuthResponse>('/api/auth/oauth', { method: 'POST', body: input });
    await setToken(res.token);
    return res;
  },
  async me(): Promise<{ user: ApiUser }> {
    return request<{ user: ApiUser }>('/api/auth/me', { auth: true });
  },
  async logout(): Promise<void> {
    await clearToken();
  },
};

