export interface ListingFilters {
  q?: string;
  brand?: string;
  condition?: ApiCondition;
  size?: string;
  minPrice?: number;
  maxPrice?: number;
  status?: ApiListingStatus | 'all';
  sort?: 'newest' | 'price_asc' | 'price_desc';
  limit?: number;
  offset?: number;
}

export interface ListingsResponse {
  listings: ApiListing[];
  total: number;
  limit: number;
  offset: number;
}

export const listings = {
  list(filters: ListingFilters = {}): Promise<ListingsResponse> {
    return request<ListingsResponse>(`/api/listings${qs(filters as Record<string, unknown>)}`);
  },
  async get(id: string): Promise<{ listing: ApiListingDetail }> {
    // The deployed API returns the detail listing FLAT (no { listing } wrapper),
    // while list endpoints wrap arrays. Normalize both so callers always get
    // { listing }. (README documents the wrapped shape; the live server differs.)
    const res = await request<ApiListingDetail | { listing: ApiListingDetail }>(
      `/api/listings/${encodeURIComponent(id)}`,
    );
    const listing =
      res && typeof res === 'object' && 'listing' in res
        ? (res as { listing: ApiListingDetail }).listing
        : (res as ApiListingDetail);
    return { listing };
  },
};

