// ─────────────────────────────────────────────────────────────
// Children (auth)
// ─────────────────────────────────────────────────────────────

// The deployed API returns single-resource writes FLAT (e.g. POST /children
// returns the child object directly, not { child }). Normalize to the wrapped
// shape the SDK documents so callers can rely on res.child.
function unwrap<T>(res: T | Record<string, T>, key: string): T {
  if (res && typeof res === 'object' && key in (res as Record<string, unknown>)) {
    return (res as Record<string, T>)[key];
  }
  return res as T;
}

export const children = {
  list(): Promise<{ children: ApiChild[] }> {
    return request<{ children: ApiChild[] }>('/api/children', { auth: true });
  },
  async create(input: { name: string; sizes: string[] }): Promise<{ child: ApiChild }> {
    const res = await request<ApiChild | { child: ApiChild }>('/api/children', {
      method: 'POST',
      body: input,
      auth: true,
    });
    return { child: unwrap(res, 'child') };
  },
  async update(id: string, input: { name?: string; sizes?: string[] }): Promise<{ child: ApiChild }> {
    const res = await request<ApiChild | { child: ApiChild }>(`/api/children/${encodeURIComponent(id)}`, {
      method: 'PATCH',
      body: input,
      auth: true,
    });
    return { child: unwrap(res, 'child') };
  },
  remove(id: string): Promise<void> {
    return request<void>(`/api/children/${encodeURIComponent(id)}`, {
      method: 'DELETE',
      auth: true,
    });
  },
};

