// ─────────────────────────────────────────────────────────────
// Display mapper — ApiListing → the shape screens already consume.
//
// ProductCard accepts EITHER a catalog `item` id OR explicit
// { brand, name, price, cond, image } props. DisplayListing is exactly that
// explicit-props shape plus { id, imageUrl }, so a screen can render an API
// listing with: <ProductCard {...toDisplayListing(l)} />.
//
// The ls-api Condition enum (cert/nib/nnb/worn/play) is identical to the app's
// ConditionKey, so condition maps straight to cond.
// ─────────────────────────────────────────────────────────────

export interface DisplayListing extends CatalogItem {
  /** API listing id — used for navigation (router.push(`/product/${id}`)). */
  id: string;
  /**
   * Catalog SKU (e.g. 'j4'). API listing ids are cuids, NOT skus, so the
   * local studio image must be resolved by THIS, via mockImage(sku).
   */
  sku: string;
  /** Listing size string from the API (e.g. '5Y'). Optional for mock rows. */
  size?: string;
  /** Remote photo URL; pass as ProductCard `image={{ uri: imageUrl }}` when set. */
  imageUrl: string | null;
}

const CONDITION_KEYS: ReadonlySet<string> = new Set<ConditionKey>([
  'cert',
  'nib',
  'nnb',
  'worn',
  'play',
]);

export function toDisplayListing(l: ApiListing): DisplayListing {
  const cond: ConditionKey = CONDITION_KEYS.has(l.condition)
    ? (l.condition as ConditionKey)
    : 'cert';
  return {
    id: l.id,
    sku: l.sku,
    size: l.size,
    brand: l.brand,
    name: l.name,
    // Prefer the derived dollar `price`; fall back to cents/100 if absent.
    price: typeof l.price === 'number' ? l.price : Math.round(l.priceCents / 100),
    cond,
    imageUrl: l.imageUrl ?? null,
  };
}
