// src/ls/storage.ts
// Web-safe auth token persistence.
//
// - Native (iOS/Android): expo-secure-store (encrypted keychain/keystore).
// - Web: localStorage when available, else an in-memory fallback.
//
// SecureStore is NEVER called on web — it warns/throws there — so every path
// is guarded by Platform.OS. All three functions are async so the API surface
// is identical across platforms.

import { Platform } from 'react-native';

const TOKEN_KEY = 'ls_auth_token';

// Lazily required so web bundles don't pull native-only code at module load.
// (require is fine here — Metro resolves it; we only call it on native.)
let SecureStore: typeof import('expo-secure-store') | null = null;
function getSecureStore() {
  if (SecureStore) return SecureStore;
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  SecureStore = require('expo-secure-store') as typeof import('expo-secure-store');
  return SecureStore;
}

// In-memory fallback for web environments with no localStorage (SSR/private mode).
let memoryToken: string | null = null;

function hasLocalStorage(): boolean {
  try {
    return typeof globalThis !== 'undefined' && typeof (globalThis as any).localStorage !== 'undefined';
  } catch {
    return false;
  }
}

export async function getToken(): Promise<string | null> {
  if (Platform.OS === 'web') {
    if (hasLocalStorage()) {
      try {
        return (globalThis as any).localStorage.getItem(TOKEN_KEY);
      } catch {
        return memoryToken;
      }
    }
    return memoryToken;
  }
  try {
    return await getSecureStore().getItemAsync(TOKEN_KEY);
  } catch {
    return null;
  }
}

export async function setToken(token: string): Promise<void> {
  if (Platform.OS === 'web') {
    if (hasLocalStorage()) {
      try {
        (globalThis as any).localStorage.setItem(TOKEN_KEY, token);
        return;
      } catch {
        memoryToken = token;
        return;
      }
    }
    memoryToken = token;
    return;
  }
  await getSecureStore().setItemAsync(TOKEN_KEY, token);
}

export async function clearToken(): Promise<void> {
  if (Platform.OS === 'web') {
    if (hasLocalStorage()) {
      try {
        (globalThis as any).localStorage.removeItem(TOKEN_KEY);
        return;
      } catch {
        memoryToken = null;
        return;
      }
    }
    memoryToken = null;
    return;
  }
  await getSecureStore().deleteItemAsync(TOKEN_KEY);
}
