import { useEffect, useState } from 'react';
import { View, Text, Pressable, ScrollView, StyleSheet, Image, ActivityIndicator, Alert, Platform } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import Animated, {
  FadeInDown,
  useSharedValue,
  useAnimatedStyle,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import {
  Screen,
  ScreenBody,
  Chip,
  LSProtect,
  PH,
  ProductCard,
  Sparkline,
  Button,
  FadeImage,
  dualCTA,
} from '@/ls/ui';
import { PressableScale, POP_SPRING } from '@/ls/motion';
import { tapMedium } from '@/ls/haptics';
import { Icon } from '@/ls/icons';
import { CONDITIONS } from '@/ls/catalog';
import { colors, radii, text } from '@/ls/theme';
import { getCatalog, getListing, mockImage } from '@/ls/data';
import { favorites, ApiError, type DisplayListing } from '@/ls/api';
import { useRequireAuth, useSession } from '@/ls/session';

const SIZES: [string, number | null][] = [
  ['4C', 64], ['5C', 68], ['6C', null], ['7C', 70],
  ['8C', 66], ['9C', null], ['10C', 72], ['11C', 75],
  ['12C', 78], ['13C', 76], ['1Y', 82], ['2Y', null],
];

const TRUST = ['Curated', 'Protected', 'No seller fees'];

// Cross-platform alert (web Alert.alert is a no-op, so fall back to window).
function notify(title: string, message?: string) {
  if (Platform.OS === 'web') {
    // eslint-disable-next-line no-alert
    if (typeof window !== 'undefined') window.alert(message ? `${title}\n\n${message}` : title);
    return;
  }
  Alert.alert(title, message);
}

export default function ProductDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const requireAuth = useRequireAuth();
  const { signedIn } = useSession();

  const [item, setItem] = useState<DisplayListing | null>(null);
  const [loading, setLoading] = useState(true);
  const [alsoLike, setAlsoLike] = useState<DisplayListing[]>([]);

  const [selSize, setSelSize] = useState('10C');
  const [faved, setFaved] = useState(false);
  const [favBusy, setFavBusy] = useState(false);

  // Heart pop — scale spring on toggle. Lives on the UI thread.
  const heartScale = useSharedValue(1);
  const heartStyle = useAnimatedStyle(() => ({ transform: [{ scale: heartScale.value }] }));

  useEffect(() => {
    let alive = true;
    setLoading(true);
    getListing(String(id))
      .then((row) => {
        if (!alive) return;
        setItem(row);
        if (row?.size) setSelSize(row.size);
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [id]);

  // "You may also like" — a few other live listings, excluding this one.
  useEffect(() => {
    let alive = true;
    getCatalog({ sort: 'newest' }).then((rows) => {
      if (alive) setAlsoLike(rows.filter((r) => r.id !== String(id)).slice(0, 4));
    });
    return () => {
      alive = false;
    };
  }, [id]);

  const onToggleFav = async () => {
    if (!item) return;
    if (!requireAuth()) return;
    setFavBusy(true);
    const next = !faved;
    setFaved(next); // optimistic
    // Pop the heart and give a light haptic on the press itself.
    tapMedium();
    heartScale.value = withSequence(
      withTiming(next ? 1.35 : 0.85, { duration: 120 }),
      withSpring(1, POP_SPRING),
    );
    try {
      if (next) await favorites.add(item.id);
      else await favorites.remove(item.id);
    } catch (e) {
      setFaved(!next); // revert
      const msg = e instanceof ApiError ? e.message : 'Could not update your saved items.';
      notify('Something went wrong', msg);
    } finally {
      setFavBusy(false);
    }
  };

  if (loading) {
    return (
      <Screen>
        <View style={styles.fullLoading}>
          <ActivityIndicator color={colors.black} />
        </View>
      </Screen>
    );
  }

  if (!item) {
    return (
      <Screen>
        <View style={styles.fullLoading}>
          <Text style={styles.notFoundTitle}>Listing not found</Text>
          <Pressable onPress={() => router.back()} hitSlop={8}>
            <Text style={styles.notFoundLink}>Go back</Text>
          </Pressable>
        </View>
      </Screen>
    );
  }

  const cond = CONDITIONS[item.cond];
  const galleryImage = item.imageUrl ? { uri: item.imageUrl } : mockImage(item.sku);

  return (
    <Screen>
      <ScreenBody contentContainerStyle={styles.body}>
        {/* full-bleed gallery */}
        <View>
          <View style={styles.gallery}>
            {galleryImage ? (
              <FadeImage
                source={galleryImage}
                resizeMode="contain"
                style={styles.galleryImg}
              />
            ) : (
              <PH label="gallery · swipe 1/4" />
            )}
          </View>
          <View style={styles.galleryBar}>
            <PressableScale style={styles.iconBtn} pressScale={0.9} onPress={() => router.back()}>
              <Icon.chevL w={20} h={20} strokeWidth={2.2} />
            </PressableScale>
            <View style={styles.galleryRight}>
              <PressableScale style={styles.iconBtn} pressScale={0.9}>
                <Icon.share w={18} h={18} strokeWidth={2} />
              </PressableScale>
              <PressableScale style={styles.iconBtn} pressScale={0.9} onPress={onToggleFav} disabled={favBusy}>
                <Animated.View style={heartStyle}>
                  <Icon.heart w={19} h={19} strokeWidth={2} fill={faved ? colors.black : 'none'} stroke={colors.black} />
                </Animated.View>
              </PressableScale>
            </View>
          </View>
          <View style={styles.dots}>
            {[0, 1, 2, 3].map((i) => (
              <View
                key={i}
                style={[
                  styles.dot,
                  { width: i === 0 ? 18 : 6, backgroundColor: i === 0 ? colors.black : 'rgba(0,0,0,0.22)' },
                ]}
              />
            ))}
          </View>
        </View>

        {/* header */}
        <Animated.View entering={FadeInDown.duration(360).delay(60)} style={styles.header}>
          <Text style={text.eyebrow}>{item.brand}</Text>
          <Text style={[text.hLg, styles.title]}>{item.name}</Text>
          <View style={styles.verRow}>
            <LSProtect />
            <Text style={text.meta}>SKU {item.sku.toUpperCase()}</Text>
          </View>

          {/* price block */}
          <View style={styles.priceBlock}>
            <View>
              <Text style={[text.cardFrom, { fontSize: 11 }]}>Lowest ask</Text>
              <Text style={text.priceBig}>${item.price}</Text>
              <Text style={[styles.lastsold, { marginTop: 2 }]}>Size {item.size ?? selSize}</Text>
            </View>
            <View style={styles.priceRight}>
              <Sparkline />
              <Text style={[text.meta, { marginTop: 2 }]}>90-day price</Text>
            </View>
          </View>
        </Animated.View>

        {/* condition box */}
        <View style={styles.condBox}>
          <Chip kind={item.cond} />
          <Text style={styles.condText}>{cond.desc} Photos show the exact pair you’ll receive.</Text>
        </View>

        {/* LS Protect box */}
        <View style={styles.protectBox}>
          <Icon.shield w={18} h={18} strokeWidth={1.9} />
          <View style={{ flex: 1 }}>
            <Text style={styles.protectTitle}>Covered by LS Protect</Text>
            <Text style={styles.protectDesc}>
              Refund or credit if it’s not as described. Every order.
            </Text>
          </View>
        </View>

        {/* size selector */}
        <View style={styles.sizeSec}>
          <View style={styles.sizeHead}>
            <Text style={text.eyebrow}>Select size · Kids</Text>
            <Text style={[styles.link, { color: colors.gray }]}>Size guide</Text>
          </View>
          <View style={styles.sizeGrid}>
            {SIZES.map(([s, p]) => {
              const sel = s === selSize;
              const out = p === null;
              return (
                <PressableScale
                  key={s}
                  disabled={out}
                  pressScale={0.94}
                  onPress={() => setSelSize(s)}
                  style={[styles.sizeCell, sel && styles.sizeCellSel, out && styles.sizeCellOut]}
                >
                  <Text style={[styles.sz, out && styles.szOut]}>{s}</Text>
                  <Text style={styles.pr}>{out ? 'Sold' : `$${p}`}</Text>
                </PressableScale>
              );
            })}
          </View>
        </View>

        {/* collapsible shipping / returns */}
        <View style={styles.rowsSec}>
          {[
            ['Shipping', 'Ships straight to your door. Arrives in 5 to 7 days.'],
            ['Returns', 'Refund or credit if it’s not as described. Every order.'],
          ].map(([t, d], i) => (
            <View
              key={t}
              style={[styles.collapseRow, i === 1 && styles.collapseRowLast]}
            >
              <View style={styles.collapseInner}>
                <View style={{ flex: 1 }}>
                  <Text style={styles.collapseTitle}>{t}</Text>
                  {i === 0 ? <Text style={[text.meta, styles.collapseDesc]}>{d}</Text> : null}
                </View>
                <Icon.chevDown w={18} h={18} strokeWidth={2} stroke={colors.gray} />
              </View>
            </View>
          ))}
        </View>

        {/* trust strip */}
        <View style={styles.trust}>
          {TRUST.map((t, i) => (
            <View key={t} style={styles.trustGroup}>
              <View style={styles.trustItem}>
                <Icon.check w={11} h={11} strokeWidth={3} />
                <Text style={styles.trustText}>{t}</Text>
              </View>
              {i < TRUST.length - 1 ? <Text style={styles.trustDot}>·</Text> : null}
            </View>
          ))}
        </View>

        {/* you may also like */}
        <View style={styles.alsoSec}>
          <View style={styles.alsoHead}>
            <Text style={[text.hMd, styles.alsoTitle]}>You may also like</Text>
          </View>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.hscroll}
          >
            {alsoLike.map((l) => (
              <View key={l.id} style={styles.alsoCell}>
                <ProductCard
                  brand={l.brand}
                  name={l.name}
                  price={l.price}
                  cond={l.cond}
                  image={l.imageUrl ? { uri: l.imageUrl } : mockImage(l.sku)}
                  onPress={() => router.push(`/product/${l.id}`)}
                />
              </View>
            ))}
          </ScrollView>
        </View>
        <View style={{ height: 8 }} />
      </ScreenBody>

      <Animated.View entering={FadeInDown.duration(340).delay(80)} style={dualCTA}>
        <Button
          label={`Buy now · $${item.price}`}
          style={styles.buyBtn}
          onPress={() => {
            if (!requireAuth()) return;
            router.push(`/checkout?listingId=${item.id}`);
          }}
        />
        <Button
          variant="outline"
          label="Make offer"
          style={styles.offerBtn}
          onPress={() => {
            if (!requireAuth()) return;
            router.push(`/offer?listingId=${item.id}`);
          }}
        />
      </Animated.View>
    </Screen>
  );
}

