// ─────────────────────────────────────────────────────────────
// ProductCard — full card. Pass `item` (catalog id) OR explicit fields.
// ─────────────────────────────────────────────────────────────
export type ProductCardProps = {
  item?: CatalogId;
  brand?: string;
  name?: string;
  price?: number;
  cond?: ConditionKey;
  label?: string;
  fav?: boolean;
  image?: any;
  onPress?: () => void;
};

export function ProductCard({
  item,
  brand,
  name,
  price,
  cond,
  label,
  fav = false,
  image,
  onPress,
}: ProductCardProps) {
  let b = brand;
  let n = name;
  let p = price;
  let c = cond;
  if (item && CATALOG[item]) {
    const it = CATALOG[item];
    b = it.brand;
    n = it.name;
    p = it.price;
    c = it.cond;
  }
  // Resolve the photo: explicit prop wins, else the catalog id's studio shot.
  const photo = image ?? (item && SHOE_IMAGES[item] ? SHOE_IMAGES[item] : null);
  return (
    <PressableScale style={styles.card} onPress={onPress}>
      <View style={[styles.cardImg, photo && styles.cardImgWhite]}>
        {photo ? (
          <View style={styles.cardPhotoPad}>
            <FadeImage source={photo} resizeMode="contain" style={styles.cardPhoto} />
          </View>
        ) : (
          <PH label={label ?? '3:4 product'} />
        )}
        <View style={styles.cardPtick}>
          <PTick />
        </View>
        <View style={styles.cardFav}>
          <Icon.heart w={15} h={15} strokeWidth={2} fill={fav ? colors.black : 'none'} stroke={colors.black} />
        </View>
        {c ? (
          <View style={styles.cardChip}>
            <Chip kind={c} />
          </View>
        ) : null}
      </View>
      <Text style={text.cardBrand}>{b}</Text>
      <Text style={[text.cardName, styles.cardName]}>{n}</Text>
      <View style={styles.cardFoot}>
        <View style={styles.cardFromRow}>
          <Text style={text.cardFrom}>From</Text>
          <Text style={text.cardPrice}>${p}</Text>
        </View>
      </View>
    </PressableScale>
  );
}

// ─────────────────────────────────────────────────────────────
// FadeImage — Image that fades in once the source has loaded. Keeps remote
// photos from popping in hard; for local requires it resolves instantly.
// ─────────────────────────────────────────────────────────────
const AnimatedImage = Animated.createAnimatedComponent(Image);

export function FadeImage({
  source,
  style,
  resizeMode = 'contain',
}: {
  source: any;
  style?: StyleProp<ImageStyle>;
  resizeMode?: 'contain' | 'cover' | 'center' | 'stretch' | 'repeat';
}) {
  const o = useSharedValue(0);
  const animatedStyle = useAnimatedStyle(() => ({
    opacity: withTiming(o.value, { duration: 260, easing: EASE_OUT }),
  }));
  return (
    <AnimatedImage
      source={source}
      resizeMode={resizeMode}
      style={[style, animatedStyle]}
      onLoad={() => {
        o.value = 1;
      }}
    />
  );
}

// ─────────────────────────────────────────────────────────────
// Skeleton — a soft pulsing placeholder block. Subtle opacity loop so a cold
// API start feels alive (premium) instead of a dead gray box.
// ─────────────────────────────────────────────────────────────
export function Skeleton({ style }: { style?: StyleProp<ViewStyle> }) {
  const pulse = useSharedValue(0);
  useEffect(() => {
    pulse.value = withRepeat(
      withSequence(
        withTiming(1, { duration: 700, easing: Easing.inOut(Easing.ease) }),
        withTiming(0, { duration: 700, easing: Easing.inOut(Easing.ease) }),
      ),
      -1,
      false,
    );
  }, [pulse]);
  const animatedStyle = useAnimatedStyle(() => ({
    opacity: 0.55 + pulse.value * 0.35,
  }));
  return <Animated.View style={[styles.skeleton, style, animatedStyle]} />;
}

// ─────────────────────────────────────────────────────────────
// Sparkline — price history mini chart via react-native-svg.
// ─────────────────────────────────────────────────────────────
export type SparklineProps = {
  pts?: number[];
  w?: number;
  h?: number;
};

export function Sparkline({
  pts = [42, 46, 44, 52, 49, 58, 55, 63, 60, 68],
  w = 120,
  h = 34,
}: SparklineProps) {
  const max = Math.max(...pts);
  const min = Math.min(...pts);
  const nx = (i: number) => (i / (pts.length - 1)) * w;
  const ny = (v: number) => h - ((v - min) / (max - min || 1)) * (h - 4) - 2;
  const d = pts
    .map((v, i) => `${i ? 'L' : 'M'}${nx(i).toFixed(1)} ${ny(v).toFixed(1)}`)
    .join(' ');
  return (
    <Svg width={w} height={h}>
      <Path
        d={d}
        fill="none"
        stroke={colors.black}
        strokeWidth={1.6}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <Circle cx={nx(pts.length - 1)} cy={ny(pts[pts.length - 1])} r={2.6} fill={colors.black} />
    </Svg>
  );
}

// ─────────────────────────────────────────────────────────────
// Button — .btn. variant solid | outline | ghost.
// ─────────────────────────────────────────────────────────────
export type ButtonProps = {
  variant?: 'solid' | 'outline' | 'ghost';
  label: string;
  onPress?: () => void;
  disabled?: boolean;
  small?: boolean;
  style?: StyleProp<ViewStyle>;
  left?: React.ReactNode;
  right?: React.ReactNode;
};

export function Button({
  variant = 'solid',
  label,
  onPress,
  disabled = false,
  small = false,
  style,
  left,
  right,
}: ButtonProps) {
  const v = btnVariants[variant];
  return (
    <PressableScale
      onPress={onPress}
      disabled={disabled}
      pressScale={0.975}
      style={[
        styles.btn,
        small && styles.btnSm,
        v.container,
        disabled && styles.btnDisabled,
        style,
      ]}
    >
      {left}
      <Text style={[styles.btnText, small && styles.btnTextSm, v.text]}>{label}</Text>
      {right}
    </PressableScale>
  );
}

// ─────────────────────────────────────────────────────────────
// CustomTabBar — matches the design's TabBar. Used by (tabs)/_layout.
// 5 items: Home / Search / Sell(center) / Activity / Profile.
// ─────────────────────────────────────────────────────────────
export type TabItem = {
  key: string;
  label: string;
  routeName: string;
};

export type CustomTabBarProps = {
  active: string; // route key currently focused
  onTabPress: (routeName: string) => void;
};

const TAB_LEFT: { key: string; label: string; icon: keyof typeof Icon; route: string }[] = [
  { key: 'index', label: 'Home', icon: 'home', route: 'index' },
  { key: 'search', label: 'Search', icon: 'search', route: 'search' },
];
const TAB_RIGHT: { key: string; label: string; icon: keyof typeof Icon; route: string }[] = [
  { key: 'activity', label: 'Activity', icon: 'bell', route: 'activity' },
  { key: 'profile', label: 'Profile', icon: 'person', route: 'profile' },
];

// A single tab item with a subtle active transition: the icon/label scale up a
// hair and a small indicator dot fades+slides in under the active tab.
function TabItem({
  t,
  isActive,
  onPress,
}: {
  t: { key: string; label: string; icon: keyof typeof Icon; route: string };
  isActive: boolean;
  onPress: () => void;
}) {
  const IconCmp = Icon[t.icon];
  const color = isActive ? colors.black : colors.gray;
  const a = useSharedValue(isActive ? 1 : 0);
  useEffect(() => {
    a.value = withTiming(isActive ? 1 : 0, { duration: 220, easing: EASE_OUT });
  }, [isActive, a]);

  const iconStyle = useAnimatedStyle(() => ({
    transform: [{ scale: 1 + a.value * 0.08 }],
  }));
  const dotStyle = useAnimatedStyle(() => ({
    opacity: a.value,
    transform: [{ scale: 0.4 + a.value * 0.6 }],
  }));

  return (
    <Pressable
      style={styles.tab}
      onPress={() => {
        tapLight();
        onPress();
      }}
    >
      <Animated.View style={iconStyle}>
        <IconCmp w={22} h={22} strokeWidth={isActive ? 2.1 : 1.8} stroke={color} />
      </Animated.View>
      <Text style={[styles.tabLabel, { color }]}>{t.label}</Text>
      <Animated.View style={[styles.tabDot, dotStyle]} />
    </Pressable>
  );
}

export function CustomTabBar({ active, onTabPress }: CustomTabBarProps) {
  const insets = useSafeAreaInsets();
  const bottomPad = (insets.bottom || chrome.homeH) + 4;

  return (
    <View style={[styles.tabbar, { paddingBottom: bottomPad }]}>
      {TAB_LEFT.map((t) => (
        <TabItem key={t.key} t={t} isActive={active === t.key} onPress={() => onTabPress(t.route)} />
      ))}
      <PressableScale
        style={styles.tab}
        pressScale={0.94}
        onPress={() => {
          tapLight();
          onTabPress('sell');
        }}
      >
        <View style={styles.tabSell}>
          <Icon.plus w={20} h={20} strokeWidth={2.4} stroke={colors.white} />
        </View>
        <Text style={[styles.tabLabel, { color: colors.black }]}>Sell</Text>
      </PressableScale>
      {TAB_RIGHT.map((t) => (
        <TabItem key={t.key} t={t} isActive={active === t.key} onPress={() => onTabPress(t.route)} />
      ))}
    </View>
  );
}

