// src/ls/haptics.ts
// Tiny haptics wrapper. Light, tasteful feedback on key moments only
// (favorite, buy/confirm, tab switch). No-ops safely on web and never throws,
// so a missing/blocked haptics engine can't break a flow.

import { Platform } from 'react-native';
import * as Haptics from 'expo-haptics';

const enabled = Platform.OS === 'ios' || Platform.OS === 'android';

/** Light tap — tab switches, chip selects. */
export function tapLight() {
  if (!enabled) return;
  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
}

/** Medium tap — favorite toggle, primary press with weight. */
export function tapMedium() {
  if (!enabled) return;
  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium).catch(() => {});
}

/** Success buzz — order confirmed. */
export function notifySuccess() {
  if (!enabled) return;
  Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
}
