import React, { useState } from 'react';
import { View, Text, Pressable, StyleSheet } from 'react-native';
import { useRouter } from 'expo-router';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { Screen, ScreenBody, TopBar, Button, Chip, Divider } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, text, fonts, chrome } from '@/ls/theme';

const SIZES = [
  '2C', '3C', '4C', '5C', '6C', '7C', '8C', '9C',
  '10C', '11C', '12C', '13C', '1Y', '2Y', '3Y', '4Y',
];
const SOLD_OUT = ['2C', '4Y'];
const INITIAL_SEL = ['10C', '13C', '1Y'];

const BRANDS = ['Nike', 'Jordan', 'Adidas', 'New Balance', 'Vans', 'Converse'];

export default function FiltersScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const close = () => router.back();

  const [selected, setSelected] = useState<string[]>(INITIAL_SEL);
  const [brands, setBrands] = useState<string[]>(['Nike', 'Jordan']);

  const toggleSize = (s: string) => {
    if (SOLD_OUT.includes(s)) return;
    setSelected((prev) =>
      prev.includes(s) ? prev.filter((x) => x !== s) : [...prev, s],
    );
  };
  const toggleBrand = (b: string) => {
    setBrands((prev) =>
      prev.includes(b) ? prev.filter((x) => x !== b) : [...prev, b],
    );
  };

  return (
    <Screen>
      <TopBar
        bordered
        left={
          <Pressable onPress={close} hitSlop={8} style={styles.topSide}>
            <Icon.x w={22} h={22} strokeWidth={2} />
          </Pressable>
        }
        title="Filters"
        right={
          <Pressable onPress={() => setSelected([])} hitSlop={8}>
            <Text style={styles.reset}>Reset</Text>
          </Pressable>
        }
      />

      <ScreenBody>
        {/* Size */}
        <View style={styles.sec}>
          <Text style={[text.eyebrow, styles.eyebrow]}>
            Size <Text style={styles.eyebrowCount}>· {selected.length} selected</Text>
          </Text>
          <View style={styles.sizeGrid}>
            {SIZES.map((s) => {
              const sel = selected.includes(s);
              const out = SOLD_OUT.includes(s);
              return (
                <Pressable
                  key={s}
                  onPress={() => toggleSize(s)}
                  disabled={out}
                  style={[
                    styles.sizeCell,
                    sel && styles.sizeCellSel,
                    out && styles.sizeCellOut,
                  ]}
                >
                  <Text style={[styles.sz, out && styles.szOut]}>{s}</Text>
                </Pressable>
              );
            })}
          </View>
        </View>
        <Divider style={styles.secDivider} />

        {/* Brand */}
        <View style={styles.sec}>
          <Text style={[text.eyebrow, styles.eyebrow]}>Brand</Text>
          {BRANDS.map((b) => {
            const checked = brands.includes(b);
            return (
              <Pressable key={b} style={styles.checkRow} onPress={() => toggleBrand(b)}>
                <View style={[styles.checkbox, checked && styles.checkboxOn]}>
                  {checked ? (
                    <Icon.check w={12} h={12} strokeWidth={3} stroke={colors.white} />
                  ) : null}
                </View>
                <Text style={styles.checkLabel}>{b}</Text>
              </Pressable>
            );
          })}
        </View>
        <Divider style={styles.secDivider} />

        {/* Condition */}
        <View style={styles.sec}>
          <Text style={[text.eyebrow, styles.eyebrow]}>Condition</Text>
          <View style={styles.condRow}>
            <Chip kind="cert" />
            <Chip kind="nib" />
            <Chip kind="worn" />
            <Chip kind="play" />
          </View>
        </View>
        <Divider style={styles.secDivider} />

        {/* Price */}
        <View style={styles.sec}>
          <Text style={[text.eyebrow, styles.eyebrowWide]}>Price · $0 &ndash; $160</Text>
          <View style={styles.sliderTrack}>
            <View style={styles.sliderFill} />
            <View style={[styles.sliderHandle, styles.sliderHandleMin]} />
            <View style={[styles.sliderHandle, styles.sliderHandleMax]} />
          </View>
          <View style={styles.priceInputs}>
            <View style={styles.priceInput}>
              <Text style={text.metaStrong}>Min</Text>
              <Text style={styles.priceVal}>$40</Text>
            </View>
            <View style={styles.priceInput}>
              <Text style={text.metaStrong}>Max</Text>
              <Text style={styles.priceVal}>$120</Text>
            </View>
          </View>
        </View>
      </ScreenBody>

      {/* Bottom CTA */}
      <View
        style={[
          styles.cta,
          { paddingBottom: (insets.bottom || chrome.homeH) + 8 },
        ]}
      >
        <Button label="Show 248 results" onPress={close} />
      </View>
    </Screen>
  );
}

