import React, { useState } from 'react';
import { View, Text, Pressable, StyleSheet, TextInput, ActivityIndicator } from 'react-native';
import { useRouter } from 'expo-router';

import { Screen, ScreenBody, TopBar, Button } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, fonts, text, letterSpacingPx } from '@/ls/theme';
import { auth, ApiError } from '@/ls/api';
import { useSession } from '@/ls/session';
import { useSocialAuth } from '@/ls/social-auth';
import { SocialButtons } from '@/ls/social-buttons';

// Create account. Real signup via auth.signup (token stored by the SDK).
export default function SignUpScreen() {
  const router = useRouter();
  const { setUser } = useSession();
  const social = useSocialAuth();

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const onCreate = async () => {
    setError(null);
    if (!name.trim() || !email.trim() || !password) {
      setError('Fill in your name, email and password to continue.');
      return;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }
    setBusy(true);
    try {
      const res = await auth.signup({ name: name.trim(), email: email.trim(), password });
      setUser(res.user);
      router.replace('/add-size');
    } catch (e) {
      if (e instanceof ApiError && e.status === 409) {
        setError('That email is already registered. Try logging in instead.');
      } else if (e instanceof ApiError) {
        setError(e.message);
      } else {
        setError('Could not create your account. Please try again.');
      }
    } finally {
      setBusy(false);
    }
  };

  return (
    <Screen>
      <TopBar
        left={
          <Pressable onPress={() => router.back()} hitSlop={8}>
            <Icon.chevL w={22} h={22} strokeWidth={2} />
          </Pressable>
        }
      />
      <ScreenBody contentContainerStyle={styles.body}>
        <Text style={text.hXl}>Create{'\n'}account</Text>
        <Text style={[text.body, styles.sub]}>
          Join Little Soles to buy, sell and track premium kids&rsquo; sneakers.
        </Text>

        <View style={styles.fields}>
          <View style={styles.field}>
            <Text style={styles.label}>Name</Text>
            <View style={styles.input}>
              <TextInput
                style={styles.inputText}
                value={name}
                onChangeText={setName}
                placeholder="Your name"
                placeholderTextColor={colors.gray2}
                autoCapitalize="words"
              />
            </View>
          </View>
          <View style={styles.field}>
            <Text style={styles.label}>Email</Text>
            <View style={styles.input}>
              <TextInput
                style={styles.inputText}
                value={email}
                onChangeText={setEmail}
                placeholder="you@email.com"
                placeholderTextColor={colors.gray2}
                autoCapitalize="none"
                autoCorrect={false}
                keyboardType="email-address"
              />
            </View>
          </View>
          <View style={styles.field}>
            <Text style={styles.label}>Password</Text>
            <View style={[styles.input, styles.inputBetween]}>
              <TextInput
                style={[styles.inputText, { flex: 1 }]}
                value={password}
                onChangeText={setPassword}
                placeholder="At least 6 characters"
                placeholderTextColor={colors.gray2}
                secureTextEntry
                autoCapitalize="none"
              />
              <Icon.lock w={17} h={17} strokeWidth={1.8} stroke={colors.gray} />
            </View>
          </View>
        </View>

        {error ? <Text style={styles.error}>{error}</Text> : null}

        <Button
          label={busy ? 'Creating…' : 'Create account'}
          onPress={onCreate}
          disabled={busy}
          style={styles.createBtn}
          right={busy ? <ActivityIndicator color={colors.white} size="small" /> : undefined}
        />

        <Pressable onPress={() => router.push('/login')} hitSlop={8} style={styles.loginRow}>
          <Text style={styles.loginText}>
            Already have an account? <Text style={styles.loginStrong}>Log in</Text>
          </Text>
        </Pressable>

        <SocialButtons social={social} />

        <Text style={styles.terms}>
          By continuing you agree to our Terms &amp; Privacy Policy.
        </Text>
      </ScreenBody>
    </Screen>
  );
}

const styles = StyleSheet.create({
  body: {
    paddingHorizontal: 24,
    paddingTop: 4,
    paddingBottom: 24,
  },
  sub: {
    marginTop: 12,
  },
  fields: {
    flexDirection: 'column',
    gap: 16,
    marginTop: 28,
  },
  field: {
    flexDirection: 'column',
    gap: 7,
  },
  label: {
    fontFamily: fonts.bold,
    fontWeight: '700',
    fontSize: 11,
    letterSpacing: letterSpacingPx(0.1, 11),
    textTransform: 'uppercase',
    color: colors.gray,
  },
  input: {
    height: 50,
    borderWidth: 1,
    borderColor: colors.line,
    borderRadius: 11,
    paddingHorizontal: 14,
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: colors.white,
  },
  inputBetween: {
    justifyContent: 'space-between',
  },
  inputText: {
    fontFamily: fonts.medium,
    fontWeight: '500',
    fontSize: 15,
    color: colors.black,
    paddingVertical: 0,
  },
  error: {
    marginTop: 16,
    fontFamily: fonts.medium,
    fontWeight: '500',
    fontSize: 13,
    color: colors.red,
  },
  createBtn: {
    marginTop: 24,
  },
  loginRow: {
    marginTop: 16,
    alignItems: 'center',
  },
  loginText: {
    fontFamily: fonts.regular,
    fontWeight: '400',
    fontSize: 13.5,
    color: colors.gray,
  },
  loginStrong: {
    fontFamily: fonts.bold,
    fontWeight: '700',
    color: colors.black,
  },
  terms: {
    ...text.meta,
    textAlign: 'center',
    marginTop: 22,
    lineHeight: 12 * 1.5,
    paddingHorizontal: 8,
  },
});
