// src/ls/data.ts
// Thin data-source facade with mock fallback. PURELY ADDITIVE.
//
// Screens can adopt this LATER to flip between mock and live API with one
// import change (see README-integration.md). Until then nothing imports it,
// so the clickable prototype is untouched.
//
// Both modes return the SAME DisplayListing shape so the consuming screen has
// one type regardless of source. In mock mode the listing `id` is the catalog
// id (e.g. 'j4'), which is exactly what the existing routes already use for
// router.push(`/product/${id}`) — so navigation keeps working unchanged.

import { USE_API } from './config';
import { CATALOG, CATALOG_IDS, SHOE_IMAGES, type CatalogId } from './catalog';
import { listings, toDisplayListing, type DisplayListing, type ListingFilters } from './api';

/** Mock catalog mapped into the DisplayListing shape (id = catalog id). */
function mockCatalog(): DisplayListing[] {
  return CATALOG_IDS.map((id: CatalogId) => {
    const it = CATALOG[id];
    return {
      id,
      // In mock mode the catalog id IS the sku, so image resolves either way.
      sku: id,
      brand: it.brand,
      name: it.name,
      price: it.price,
      cond: it.cond,
      // Mock listings carry no remote URL; the local studio shot is resolved
      // separately via mockImage(sku) for ProductCard's `image` prop.
      imageUrl: null,
    };
  });
}

/**
 * Resolve the local bundled studio shot for a mock catalog id.
 * Returns undefined for API ids (those use `imageUrl` instead).
 */
export function mockImage(id: string): any | undefined {
  return (SHOE_IMAGES as Record<string, any>)[id];
}

/**
 * Catalog feed for shelves/grids.
 * - API on  → GET /listings mapped to DisplayListing.
 * - API off → mock catalog.
 * On API error, falls back to mock and warns (so screens never hard-fail).
 */
export async function getCatalog(filters: ListingFilters = {}): Promise<DisplayListing[]> {
  if (!USE_API) return mockCatalog();
  try {
    const res = await listings.list(filters);
    return res.listings.map(toDisplayListing);
  } catch (err) {
    console.warn('[ls/data] getCatalog API failed, falling back to mock:', err);
    return mockCatalog();
  }
}

/**
 * Single listing for the product detail screen.
 * - API on  → GET /listings/:id mapped to DisplayListing.
 * - API off → mock lookup by catalog id.
 * Returns null if not found (mock) or on API error after fallback miss.
 */
export async function getListing(id: string): Promise<DisplayListing | null> {
  if (!USE_API) {
    const it = (CATALOG as Record<string, (typeof CATALOG)[CatalogId]>)[id];
    if (!it) return null;
    return { id, sku: id, brand: it.brand, name: it.name, price: it.price, cond: it.cond, imageUrl: null };
  }
  try {
    const res = await listings.get(id);
    return toDisplayListing(res.listing);
  } catch (err) {
    console.warn('[ls/data] getListing API failed, falling back to mock:', err);
    const it = (CATALOG as Record<string, (typeof CATALOG)[CatalogId]>)[id];
    return it ? { id, sku: id, brand: it.brand, name: it.name, price: it.price, cond: it.cond, imageUrl: null } : null;
  }
}
